package com.contextgraph.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List; @Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt; public JwtAuthenticationFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){var a=new UsernamePasswordAuthenticationToken(jwt.subject(t),null,List.of());SecurityContextHolder.getContext().setAuthentication(a);}}c.doFilter(r,p);}}